window.FreshCap={render:function(e,s){const n=document.querySelector(e),a=document.createElement("div");a.className="freshcap-container",a.innerHTML='\n      <div class="freshcap-checkbox"></div>\n      <div class="freshcap-label">I\'m not a robot</div>\n      <div class="freshcap-badge">FreshCap</div>\n      <div class="freshcap-popup"></div>\n    ',n.appendChild(a);const t=a.querySelector(".freshcap-checkbox"),i=a.querySelector(".freshcap-popup");let c=null;const r='\n      <svg class="freshcap-verified-icon" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">\n        <path d="M20 6L9 17l-5-5"/>\n      </svg>\n    ';t.addEventListener("click",()=>{c?i.classList.toggle("active"):fetch("/v1/challenge",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({site_key:s.siteKey})}).then(e=>e.json()).then(e=>{if(c=e,i.innerHTML="",i.classList.add("active"),"slider"===c.type){i.innerHTML=`\n              <div class="freshcap-hint">${c.challenge_payload.hint}</div>\n              <input type="range" min="0" max="100" value="0" class="freshcap-range">\n              <div class="freshcap-status">Slide to verify</div>\n            `;const e=i.querySelector(".freshcap-range"),n=i.querySelector(".freshcap-status");e.addEventListener("input",()=>{e.style.background=`linear-gradient(to right, #6366f1 ${e.value}%, #374151 ${e.value}%)`}),e.addEventListener("change",()=>{fetch("/v1/verify",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({site_key:s.siteKey,challenge_id:c.challenge_id,response:{position:parseInt(e.value)}})}).then(e=>e.json()).then(s=>{s.success?(t.classList.add("checked"),t.innerHTML=r,i.classList.remove("active"),n.innerText="Verified",n.classList.add("freshcap-success"),n.classList.add("pop-up"),window.parent.postMessage({freshcapToken:s.token},"*")):(n.innerText="Try again",e.value=0,e.style.background="")})})}if("question"===c.type){i.innerHTML=`\n              <div class="freshcap-question">${c.challenge_payload.question}</div>\n              <input type="text" class="freshcap-answer" placeholder="Your answer...">\n              <button class="freshcap-submit">Verify</button>\n              <div class="freshcap-status">Enter your answer above</div>\n            `;const e=i.querySelector(".freshcap-answer"),n=i.querySelector(".freshcap-status");i.querySelector(".freshcap-submit").addEventListener("click",()=>{fetch("/v1/verify",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({site_key:s.siteKey,challenge_id:c.challenge_id,response:{answer:e.value}})}).then(e=>e.json()).then(s=>{s.success?(t.classList.add("checked"),t.innerHTML=r,i.classList.remove("active"),n.innerText="Verified",n.classList.add("freshcap-success"),n.classList.add("pop-up"),window.parent.postMessage({freshcapToken:s.token},"*")):(n.innerText="Wrong, try again",e.value="",e.classList.add("shake"),setTimeout(()=>e.classList.remove("shake"),500))})})}})})}};